<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['guardar'])){$id=(int)($_POST['id']??0);$data=[epost('nombre'),epost('contacto'),epost('telefono'),epost('email'),epost('pais'),eint('tiempo_entrega_dias'),epost('notas')];if($data[0]!==''){if($id)$pdo->prepare('UPDATE proveedores SET nombre=?,contacto=?,telefono=?,email=?,pais=?,tiempo_entrega_dias=?,notas=?,activo=1 WHERE id=?')->execute([...$data,$id]);else$pdo->prepare('INSERT INTO proveedores(nombre,contacto,telefono,email,pais,tiempo_entrega_dias,notas,activo) VALUES(?,?,?,?,?,?,?,1)')->execute($data);}}
 if(isset($_POST['toggle']))$pdo->prepare('UPDATE proveedores SET activo=IF(activo=1,0,1) WHERE id=?')->execute([(int)$_POST['id']]);ego('proveedores.php');
}
$edit=null;if(($id=(int)($_GET['edit']??0))){$s=$pdo->prepare('SELECT * FROM proveedores WHERE id=?');$s->execute([$id]);$edit=$s->fetch()?:null;}$rows=$pdo->query('SELECT p.*,(SELECT COUNT(*) FROM compras c WHERE c.proveedor_id=p.id) compras,(SELECT COALESCE(SUM(total),0) FROM compras c WHERE c.proveedor_id=p.id) total_compras FROM proveedores p ORDER BY activo DESC,nombre')->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Proveedores · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('compras');?><main class="w"><div class="srnu-page-heading"><div><h1>Proveedores</h1><p>Contactos, tiempos de entrega y compras acumuladas.</p></div><a class="btn blue" href="compras.php">Compras</a></div><section class="panel" style="padding:18px"><form method="post" class="erp-form cols-4"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><input name="nombre" required placeholder="Proveedor" value="<?=eh($edit['nombre']??'')?>"><input name="contacto" placeholder="Contacto" value="<?=eh($edit['contacto']??'')?>"><input name="telefono" placeholder="Teléfono" value="<?=eh($edit['telefono']??'')?>"><input type="email" name="email" placeholder="Email" value="<?=eh($edit['email']??'')?>"><input name="pais" placeholder="País" value="<?=eh($edit['pais']??'')?>"><input type="number" min="0" name="tiempo_entrega_dias" placeholder="Entrega promedio (días)" value="<?=eh($edit['tiempo_entrega_dias']??0)?>"><input class="full" name="notas" placeholder="Notas" value="<?=eh($edit['notas']??'')?>"><div class="toolbar full"><button class="btn blue" name="guardar" value="1">Guardar proveedor</button><?php if($edit):?><a class="btn light" href="proveedores.php">Cancelar</a><?php endif;?></div></form></section><section class="tablebox" style="margin-top:16px"><table><thead><tr><th>Proveedor</th><th>Contacto</th><th>Entrega</th><th>Compras</th><th>Total comprado</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr style="<?=$r['activo']?'':'opacity:.5'?>"><td><b><?=eh($r['nombre'])?></b><div class="muted"><?=eh($r['pais'])?></div></td><td><?=eh($r['contacto'])?><div class="muted"><?=eh($r['telefono'])?> · <?=eh($r['email'])?></div></td><td><?=(int)$r['tiempo_entrega_dias']?> días</td><td><?=(int)$r['compras']?></td><td><?=emoney($r['total_compras'])?></td><td><a class="btn light" href="?edit=<?=$r['id']?>">Editar</a><form method="post" style="display:inline"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn <?=$r['activo']?'danger':'green'?>" name="toggle" value="1"><?=$r['activo']?'Desactivar':'Activar'?></button></form></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
